mapper.update:
update clazz
name = #{name}, room = #{room}, begin_date = #{beginDate}, end_date = #{endDate}, master_id = #{masterId}, subject = #{subject},
where id = #{id}

mapper.select:
SELECT e.id, e.name, e.room, e.begin_date AS beginDate, e.end_date AS endDate, e.master_id AS masterId, e.subject, e.create_time AS createTime, e.update_time AS updateTime, emp.name AS masterName, COUNT(s.id) AS studentCount, CASE WHEN e.begin_date > CURDATE() THEN '未开班' WHEN e.end_date < CURDATE() THEN '已结课' ELSE '进行中' END AS status FROM clazz e LEFT JOIN emp emp ON e.master_id = emp.id LEFT JOIN student s ON e.id = s.clazz_id
AND e.name LIKE CONCAT('%', #{name}, '%')
AND e.begin_date >= #{begin}
AND e.end_date <= #{end}
GROUP BY e.id, e.name, e.room, e.begin_date, e.end_date, e.master_id, e.subject, e.create_time, e.update_time, emp.name
